begin;
create table if not exists public.dashboard_settings (key text primary key default 'main',title text not null,subtitle text not null default '',hero_text text not null default '',support_text text not null default '',audit_text text not null default '',active boolean not null default true,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.dashboard_goals (id uuid primary key default gen_random_uuid(),slug text not null unique check(slug~'^[a-z0-9]+(?:-[a-z0-9]+)*$'),icon text not null default '○',title text not null,description text not null default '',active boolean not null default true,sort_order integer not null default 0,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.dashboard_products (id uuid primary key default gen_random_uuid(),slug text not null unique check(slug~'^[a-z0-9]+(?:-[a-z0-9]+)*$'),name text not null,scientific_family text not null default '',category text not null default '',level text not null default '',presentation text not null default '',short_summary text not null default '',pitch text not null default '',studied_for text not null default '',research_shows text not null default '',important_note text not null default '',image_url text not null default '',buy_url text not null default '',active boolean not null default true,sort_order integer not null default 0,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.dashboard_product_goals (product_id uuid not null references public.dashboard_products(id) on delete cascade,goal_id uuid not null references public.dashboard_goals(id) on delete cascade,primary key(product_id,goal_id));
create table if not exists public.dashboard_questions (id uuid primary key default gen_random_uuid(),question text not null,answer text not null default '',category text not null default '',active boolean not null default true,sort_order integer not null default 0,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.dashboard_sections (id uuid primary key default gen_random_uuid(),title text not null,body text not null default '',section_type text not null default 'text',active boolean not null default true,sort_order integer not null default 0,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create index if not exists dashboard_goals_order_idx on public.dashboard_goals(sort_order);create index if not exists dashboard_products_family_order_idx on public.dashboard_products(scientific_family,sort_order);create index if not exists dashboard_questions_order_idx on public.dashboard_questions(sort_order);create index if not exists dashboard_sections_order_idx on public.dashboard_sections(sort_order);
alter table public.dashboard_settings enable row level security;alter table public.dashboard_goals enable row level security;alter table public.dashboard_products enable row level security;alter table public.dashboard_product_goals enable row level security;alter table public.dashboard_questions enable row level security;alter table public.dashboard_sections enable row level security;
create policy "active dashboard settings public" on public.dashboard_settings for select to anon,authenticated using(active);create policy "active dashboard goals public" on public.dashboard_goals for select to anon,authenticated using(active);create policy "active dashboard products public" on public.dashboard_products for select to anon,authenticated using(active);create policy "dashboard product goals public" on public.dashboard_product_goals for select to anon,authenticated using(exists(select 1 from public.dashboard_products p where p.id=product_id and p.active) and exists(select 1 from public.dashboard_goals g where g.id=goal_id and g.active));create policy "active dashboard questions public" on public.dashboard_questions for select to anon,authenticated using(active);create policy "active dashboard sections public" on public.dashboard_sections for select to anon,authenticated using(active);
commit;
